namespace sv_9e1ba7f8daf9461da7eecd9a73066356.Services;

public class WarehouseState
{
    private string _selectedWarehouseId = "WH-001";

    public string SelectedWarehouseId => _selectedWarehouseId;

    public string SelectedWarehouseName =>
        Warehouses.TryGetValue(_selectedWarehouseId, out var name) ? name : _selectedWarehouseId;

    // Static list of warehouses (would come from a DB in production)
    public static readonly Dictionary<string, string> Warehouses = new()
    {
        ["WH-001"] = "Warehouse A — Downtown",
        ["WH-002"] = "Warehouse B — Airport",
        ["WH-003"] = "Warehouse C — Harbor",
    };

    public event Action? OnChange;

    public void SetWarehouse(string warehouseId)
    {
        if (_selectedWarehouseId == warehouseId) return;
        _selectedWarehouseId = warehouseId;
        OnChange?.Invoke();
    }
}

