@using sv_9e1ba7f8daf9461da7eecd9a73066356.Services
@inject WarehouseState Warehouse
@implements IDisposable
@inject InventoryAlertService AlertService

<div class="d-flex align-items-center gap-2">
    <label class="text-white mb-0 small" for="warehouse-select">Site:</label>
    <select id="warehouse-select"
            class="form-select form-select-sm"
            style="width: auto;"
            value="@Warehouse.SelectedWarehouseId"
            @onchange="OnWarehouseChanged">
        @foreach (var wh in WarehouseState.Warehouses)
        {
            <option value="@wh.Key">@wh.Value</option>
        }
    </select>
</div>

@code {
    private void OnWarehouseChanged(ChangeEventArgs e)
    {
        var newId = e.Value?.ToString();
        if (!string.IsNullOrEmpty(newId))
        {
            Warehouse.SetWarehouse(newId);
        }
    }

    // When warehouse changes, immediately refresh alerts so all subscribers
    // see updated counts for the new warehouse.
    private Action? _warehouseHandler;

    protected override void OnInitialized()
    {
        _warehouseHandler = async () =>
        {
            await AlertService.RefreshAsync();
            await InvokeAsync(StateHasChanged);
        };
        Warehouse.OnChange += _warehouseHandler;
    }

    public void Dispose()
    {
        Warehouse.OnChange -= _warehouseHandler;
    }
}

@using sv_9e1ba7f8daf9461da7eecd9a73066356.Services
@inject InventoryAlertService AlertService
@implements IDisposable

@if (AlertService.CurrentAlertCount > 0)
{
    <span class="badge bg-danger rounded-pill ms-2" title="Low-stock alerts">
        @AlertService.CurrentAlertCount
    </span>
}
else
{
    <span class="badge bg-success rounded-pill ms-2" title="No low-stock alerts">
        0
    </span>
}

@code {
    private Action? _handler;

    protected override void OnInitialized()
    {
        _handler = () => InvokeAsync(StateHasChanged);
        AlertService.OnAlertCountChanged += _handler;
    }

    public void Dispose()
    {
        AlertService.OnAlertCountChanged -= _handler;
    }
}

