@using sv_9e1ba7f8daf9461da7eecd9a73066356.Services
@inject WarehouseState Warehouse
@inject InventoryAlertService AlertService
@implements IDisposable

<h1>Warehouse Dashboard</h1>
<p class="lead">
    Currently viewing: <strong>@Warehouse.SelectedWarehouseName</strong>
    <span class="text-muted small">(@Warehouse.SelectedWarehouseId)</span>
</p>

<div class="row mt-4">
    <div class="col-md-4">
        <div class="card @(AlertService.CurrentAlertCount > 0 ? "border-danger" : "border-success")">
            <div class="card-body text-center">
                <h5 class="card-title">Low-Stock Alerts</h5>
                <p class="display-4 @(AlertService.CurrentAlertCount > 0 ? "text-danger" : "text-success")">
                    @AlertService.CurrentAlertCount
                </p>
                <p class="text-muted small mb-0">
                    Items below minimum level &middot; refreshes every 10 s
                </p>
            </div>
        </div>
    </div>

    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Selected Site</h5>
                <p class="display-6">@Warehouse.SelectedWarehouseName</p>
                <p class="text-muted small mb-0">
                    Switch warehouses using the dropdown above
                </p>
            </div>
        </div>
    </div>

    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Polling Status</h5>
                <p class="display-6 text-success">Active</p>
                <p class="text-muted small mb-0">
                    Polling stops when you leave this page
                </p>
            </div>
        </div>
    </div>
</div>

@code {
    private Action? _alertHandler;
    private Action? _warehouseHandler;

    protected override void OnInitialized()
    {
        // Subscribe to alert changes (fired from background thread)
        _alertHandler = () => InvokeAsync(StateHasChanged);
        AlertService.OnAlertCountChanged += _alertHandler;

        // Subscribe to warehouse changes (fired from UI thread)
        _warehouseHandler = () => InvokeAsync(StateHasChanged);
        Warehouse.OnChange += _warehouseHandler;

        // Start polling — stops in Dispose when user leaves the page
        AlertService.StartPolling();
    }

    public void Dispose()
    {
        AlertService.StopPolling();
        AlertService.OnAlertCountChanged -= _alertHandler;
        Warehouse.OnChange -= _warehouseHandler;
    }
}

